نقش سازمانی: مدیر تولید معدن (mining_production_manager)

درخواست کاربر:
هزینهٔ هر تن این ماه نسبت به ماه قبل 23٪ بالا رفته در حالی که نرخ سوخت تغییری نداشته. دقیقاً کجای زنجیرهٔ هزینه شکسته؟ (مدیر تولید معدن — مجتمع معدنی گل‌گهر)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "cost_ledger",
      "description": "هزینهٔ عملیاتی به تفکیک جزء (سوخت، قطعات، دستمزد، پیمانکار)",
      "dimensions": [
        "component",
        "period"
      ],
      "measures": [
        "toman_per_ton"
      ]
    },
    {
      "dataset": "haul_report",
      "description": "گزارش حمل: مسافت، تن-کیلومتر و مصرف سوخت کامیون‌ها",
      "dimensions": [
        "route",
        "period"
      ],
      "measures": [
        "distance_km",
        "tons",
        "liter"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "cost_per_ton",
      "description": "هزینهٔ عملیاتی هر تن",
      "formula": "هزینهٔ کل / تن فرآوری‌شده",
      "unit": "تومان بر تن",
      "dimensions": [
        "component",
        "period"
      ]
    },
    {
      "metric": "fuel_per_ton",
      "description": "مصرف سوخت به‌ازای هر تن",
      "formula": "لیتر مصرفی / تن",
      "unit": "لیتر بر تن",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با دو پیت فعال و کارخانهٔ فرآوری مجاور",
    "برنامهٔ تولید ماهانه و شاخص‌های فنی هفته‌به‌هفته به‌روز می‌شود",
    "تأمین مالی عملیات از محل فروش کنسانتره و تسهیلات بانکی"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "cost_per_ton"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month"
  }
}

TOOL_OBSERVATION:
{
  "cost_per_ton_toman": {
    "prev_month": 63000,
    "curr_month": 77500,
    "change": 14500
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "cost_ledger",
    "filters": {
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "components_toman_per_ton": {
    "سوخت": 5265,
    "قطعات و لاستیک": 6464,
    "دستمزد و پیمانکار": 2770
  },
  "share_of_fuel_in_rise_pct": 36
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "haul_report",
    "filters": {
      "period": [
        "prev_month",
        "curr_month"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "fuel_liter_per_ton": {
    "prev_month": 1.95,
    "curr_month": 2.76
  },
  "haul_distance_km": {
    "prev_month": 4.2,
    "curr_month": 6.300000000000001,
    "note": "پیشروی پیت به عمق و جابه‌جایی دامپ به فاصلهٔ دورتر"
  }
}

نقش سازمانی: مدیر تولید معدن (mining_production_manager)

درخواست کاربر:
بازیابی کارخانه این ماه از 87٪ به 81٪ افت کرده در حالی که خوراک تقریباً ثابت بوده. دلیلش چیست؟ (مدیر تولید معدن — معدن سنگ‌آهن چادرملو)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "processing_plant",
      "description": "خوراک، بازیابی و کنسانترهٔ کارخانه",
      "dimensions": [
        "month"
      ],
      "measures": [
        "feed_tons",
        "grade_pct",
        "recovery_pct",
        "concentrate_tons"
      ]
    },
    {
      "dataset": "grade_control",
      "description": "عیار سنگ خوراک به تفکیک پیت و ماه",
      "dimensions": [
        "pit",
        "month"
      ],
      "measures": [
        "grade_pct"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "recovery_rate",
      "description": "نرخ بازیابی کارخانه",
      "formula": "فلز بازیابی‌شده / فلز موجود در خوراک",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "ore_grade",
      "description": "عیار سنگ خوراک",
      "formula": "وزن فلز مفید / وزن سنگ",
      "unit": "درصد",
      "dimensions": [
        "pit",
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با دو پیت فعال و کارخانهٔ فرآوری مجاور",
    "برنامهٔ تولید ماهانه و شاخص‌های فنی هفته‌به‌هفته به‌روز می‌شود"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "recovery_rate"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month"
  }
}

TOOL_OBSERVATION:
{
  "recovery_pct": {
    "prev_month": 87,
    "curr_month": 81,
    "change": -6
  },
  "feed_tons": {
    "prev_month": 540000,
    "curr_month": 540000
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "grade_control",
    "filters": {
      "period": [
        "prev_month",
        "curr_month"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "feed_grade_pct": {
    "prev_month": 1.03,
    "curr_month": 0.85
  },
  "feed_source": {
    "note": "از ۱۲ام ماه، ۳۵٪ خوراک از «پیت جنوبی» (سنگ گوگرددار) تأمین می‌شود بدون تغییر در تنظیم فلوتاسیون"
  }
}

