نقش سازمانی: مدیر تولید معدن (mining_production_manager)

درخواست کاربر:
به‌عنوان مدیرعامل می‌خواهم بدانم مهم‌ترین ریسک تولید-مالی این ماه چیست و اولویت ما کجا باشد. (مدیر تولید معدن در گفتگو با مدیرعامل — معدن روی مهدی‌آباد)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "production_plan_actual",
      "description": "برنامه و واقعی استخراج به تفکیک پیت و هفته",
      "dimensions": [
        "pit",
        "week"
      ],
      "measures": [
        "plan_tons",
        "actual_tons"
      ]
    },
    {
      "dataset": "cost_ledger",
      "description": "هزینهٔ عملیاتی به تفکیک جزء (سوخت، قطعات، دستمزد، پیمانکار)",
      "dimensions": [
        "component",
        "period"
      ],
      "measures": [
        "toman_per_ton"
      ]
    },
    {
      "dataset": "grade_control",
      "description": "عیار سنگ خوراک به تفکیک پیت و ماه",
      "dimensions": [
        "pit",
        "month"
      ],
      "measures": [
        "grade_pct"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "extraction_rate",
      "description": "نرخ استخراج",
      "formula": "تن استخراج‌شده / روزهای کاری",
      "unit": "تن در روز",
      "dimensions": [
        "pit",
        "period"
      ]
    },
    {
      "metric": "cost_per_ton",
      "description": "هزینهٔ عملیاتی هر تن",
      "formula": "هزینهٔ کل / تن فرآوری‌شده",
      "unit": "تومان بر تن",
      "dimensions": [
        "component",
        "period"
      ]
    },
    {
      "metric": "ore_grade",
      "description": "عیار سنگ خوراک",
      "formula": "وزن فلز مفید / وزن سنگ",
      "unit": "درصد",
      "dimensions": [
        "pit",
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با دو پیت فعال و کارخانهٔ فرآوری مجاور",
    "برنامهٔ تولید ماهانه و شاخص‌های فنی هفته‌به‌هفته به‌روز می‌شود",
    "تأمین مالی عملیات از محل فروش کنسانتره و تسهیلات بانکی"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "extraction_rate",
    "period_a": "plan",
    "period_b": "actual"
  }
}

TOOL_OBSERVATION:
{
  "extraction_attainment_pct": 98
}

