نقش سازمانی: مدیر تولید معدن (mining_production_manager)

درخواست کاربر:
مصرف انرژی به‌ازای تن هفتهٔ گذشته یک‌باره 30 واحد جهش کرده. این جهش چیست و آیا روند ما بد شده؟ (مدیر تولید معدن — معدن سنگ‌آهن چادرملو)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "energy_consumption",
      "description": "مصرف انرژی به تفکیک پیت و هفته",
      "dimensions": [
        "pit",
        "week"
      ],
      "measures": [
        "kwh"
      ]
    },
    {
      "dataset": "equipment_downtime",
      "description": "ساعت توقف تجهیزات به تفکیک تجهیز و علت",
      "dimensions": [
        "equipment",
        "reason",
        "period"
      ],
      "measures": [
        "hours"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "energy_per_ton",
      "description": "مصرف انرژی به‌ازای هر تن",
      "formula": "کیلووات‌ساعت مصرفی / تن",
      "unit": "کیلووات‌ساعت بر تن",
      "dimensions": [
        "pit",
        "period"
      ]
    },
    {
      "metric": "equipment_downtime",
      "description": "توقف برنامه‌ریزی‌نشدهٔ تجهیزات",
      "formula": "مجموع ساعت توقف",
      "unit": "ساعت",
      "dimensions": [
        "equipment",
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با دو پیت فعال و کارخانهٔ فرآوری مجاور",
    "برنامهٔ تولید ماهانه و شاخص‌های فنی هفته‌به‌هفته به‌روز می‌شود"
  ]
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "energy_per_ton",
    "granularity": "week",
    "range": "last_4_weeks"
  }
}

TOOL_OBSERVATION:
{
  "energy_per_ton_weekly": [
    {
      "week": 1,
      "kwh_per_ton": 21
    },
    {
      "week": 2,
      "kwh_per_ton": 22
    },
    {
      "week": 3,
      "kwh_per_ton": 51
    },
    {
      "week": 4,
      "kwh_per_ton": 21
    }
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "equipment_downtime",
    "filters": {
      "period": "week_3"
    }
  }
}

TOOL_OBSERVATION:
{
  "week3": {
    "توقف سنگ‌شکن اولیه (تعمیر اضطراری): 6 ساعت": 6,
    "گردش بی‌بار نوارها و آسیاب هنگام توقف و راه‌اندازی": "منبع اصلی مصرف اضافه",
    "note": "رخداد هفتهٔ ۳؛ سایر هفته‌ها بدون توقف غیرعادی"
  }
}

