عیار سنگ سه ماه است پایین آمده و زمین‌شناس می‌گوید ذخیره رو به اتمام است و باید برای کاهش تولید برنامه‌ریزی کنیم. این نتیجه‌گیری چقدر معتبر است؟ (مدیر تولید معدن — مجتمع معدنی گل‌گهر)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "grade_control",
      "description": "عیار سنگ خوراک به تفکیک پیت و ماه",
      "dimensions": [
        "pit",
        "month"
      ],
      "measures": [
        "grade_pct"
      ]
    },
    {
      "dataset": "production_plan_actual",
      "description": "برنامه و واقعی استخراج به تفکیک پیت و هفته",
      "dimensions": [
        "pit",
        "week"
      ],
      "measures": [
        "plan_tons",
        "actual_tons"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ore_grade",
      "description": "عیار سنگ خوراک",
      "formula": "وزن فلز مفید / وزن سنگ",
      "unit": "درصد",
      "dimensions": [
        "pit",
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با دو پیت فعال و کارخانهٔ فرآوری مجاور",
    "برنامهٔ تولید ماهانه و شاخص‌های فنی هفته‌به‌هفته به‌روز می‌شود",
    "تأمین مالی عملیات از محل فروش کنسانتره و تسهیلات بانکی"
  ]
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "ore_grade",
    "granularity": "month",
    "range": "last_3_months"
  }
}

TOOL_OBSERVATION:
{
  "grade_monthly": [
    {
      "month": "مرداد",
      "grade_pct": 0.79
    },
    {
      "month": "شهریور",
      "grade_pct": 0.76
    }
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "production_plan_actual",
    "filters": {
      "period": "next_quarter"
    }
  }
}

نقش سازمانی: مدیر تولید معدن (mining_production_manager)

درخواست کاربر:
بازیابی کارخانه این ماه از 85٪ به 80٪ افت کرده در حالی که خوراک تقریباً ثابت بوده. دلیلش چیست؟ (مدیر تولید معدن — معدن روی مهدی‌آباد)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "processing_plant",
      "description": "خوراک، بازیابی و کنسانترهٔ کارخانه",
      "dimensions": [
        "month"
      ],
      "measures": [
        "feed_tons",
        "grade_pct",
        "recovery_pct",
        "concentrate_tons"
      ]
    },
    {
      "dataset": "grade_control",
      "description": "عیار سنگ خوراک به تفکیک پیت و ماه",
      "dimensions": [
        "pit",
        "month"
      ],
      "measures": [
        "grade_pct"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "recovery_rate",
      "description": "نرخ بازیابی کارخانه",
      "formula": "فلز بازیابی‌شده / فلز موجود در خوراک",
      "unit": "درصد",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "ore_grade",
      "description": "عیار سنگ خوراک",
      "formula": "وزن فلز مفید / وزن سنگ",
      "unit": "درصد",
      "dimensions": [
        "pit",
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با دو پیت فعال و کارخانهٔ فرآوری مجاور",
    "برنامهٔ تولید ماهانه و شاخص‌های فنی هفته‌به‌هفته به‌روز می‌شود"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "recovery_rate"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month"
  }
}

