    {
      "metric": "equipment_downtime",
      "description": "توقف برنامه‌ریزی‌نشدهٔ تجهیزات",
      "formula": "مجموع ساعت توقف",
      "unit": "ساعت",
      "dimensions": [
        "equipment",
        "period"
      ]
